/**
 * @name ReDoS in glob implementation
 * @description Checks for regular expressions created from function arguments, which might lead to ReDoS.
 * @kind problem
 * @problem.severity warning
 * @id py/redos-glob
 * @tags security
 *       external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ReDoSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("re").getMember(["compile", "match", "search", "findall", "finditer", "fullmatch", "split", "sub", "subn"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module ReDoSFlow = TaintTracking::Global<ReDoSConfig>;

from DataFlow::Node source, DataFlow::Node sink
where ReDoSFlow::flow(source, sink)
select sink, "Potential ReDoS: Regular expression constructed from parameter $@.", source, source.toString()

/**
 * @name Potential Zip Slip Vulnerability
 * @description Detects usage of zip file paths in filesystem operations without sanitization.
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: Names from a ZipFile
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember("namelist").getACall() and
      source = call
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember("infolist").getACall() and
      source = call
    )
    // Also consider zipp's own Path objects if they expose raw names
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: File system operations
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("path").getMember("join").getACall() and
      sink = call.getArg(1)
    )
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential Zip Slip: Path from zip file used in filesystem operation."

/**
 * @name Potential Path Traversal in posixpath.join
 * @description constructing paths with posixpath.join using function parameters might lead to path traversal.
 * @kind problem
 * @problem.severity warning
 * @id py/zipp-posixpath-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("posixpath").getMember("join").getACall() and
      sink = call.getArg(_)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;

from DataFlow::Node source, DataFlow::Node sink
where PathTraversalFlow::flow(source, sink)
select sink, "Potential path traversal: argument to posixpath.join derived from parameter $@.", source, source.toString()
